let savedState = null; try { savedState = JSON.parse(localStorage.getItem('whyme_state_v3') || 'null') } catch (e) { }
let state = savedState || { selected: [], answers: {}, quizDone: false, results: null, booking: null, trial: {}, name: '' };
let current = 'home', activeJob = 'ux', filter = 'Усі', searchTerm = '', qindex = 0, selectedMentor = null, chosenTime = null;
function persist() { try { localStorage.setItem('whyme_state_v3', JSON.stringify(state)) } catch (e) { } }
function img(id, w = 700) { return id.startsWith('assets/') ? id : PHOTO + id + '?auto=format&fit=crop&w=' + w + '&q=82' }
function esc(s) { return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])) }
function toast(t) { const e = document.getElementById('toast'); e.textContent = t; e.classList.add('visible'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => e.classList.remove('visible'), 2900) }
function navigate(page) { current = page; document.getElementById('navlinks').classList.remove('open'); document.getElementById('modalroot').innerHTML = ''; render(); window.scrollTo({ top: 0, behavior: 'smooth' }) }
function startFlow() { navigate(state.selected.length ? 'quiz' : 'jobs') }
function jobCard(job) {
  const sel = state.selected.includes(job.id);
  return `<div class="job-card" id="job-${job.id}" role="button" tabindex="0" aria-label="${esc(job.title)}. Натисни, щоб ${'перевернути картку і прочитати опис'}" aria-expanded="false" onclick="handleJobCardClick(event,'${job.id}')" onkeydown="handleJobCardKey(event,'${job.id}')">
    <div class="job-inner">
      <div class="job-front">
        <img loading="lazy" src="${img(job.image, 500)}" alt="${esc(job.title)}" onerror="this.style.opacity='.1'">
        <span class="turn-btn" aria-hidden="true">↗</span>
        ${sel ? '<span class="selected-mark">✓ У твоїй колекції</span>' : ''}
        <div class="job-title"><small>${esc(job.cat)}</small><b>${esc(job.title)}</b><span class="job-discover">Натисни, щоб дізнатися більше <span aria-hidden="true">↗</span></span></div>
      </div>
      <div class="job-back">
        <span class="turn-btn backclose" aria-hidden="true">↶</span>
        <span class="tag">ПРОФЕСІЯ ЗСЕРЕДИНИ</span>
        <h3>${esc(job.title)}</h3>
        <p>${esc(job.desc)}</p>
        <p><b>Спробуй уявити:</b> ${esc(job.day)}</p>
        <button type="button" class="btn btn-small" onclick="event.stopPropagation();toggleJob('${job.id}')">${sel ? '✓ Прибрати з вибраного' : '＋ Обрати професію'}</button>
        <button class="details-link" onclick="event.stopPropagation();openJobDetail('${job.id}')">Детальніше про професію ↗</button><span class="job-return">Натисни на картку, щоб повернути фото ↶</span>
      </div>
    </div>
  </div>`;
}
function flipJob(id) {
  const card = document.getElementById('job-' + id);
  if (!card) return;
  const open = card.classList.toggle('flipped');
  card.setAttribute('aria-expanded', String(open));
}
function handleJobCardClick(event, id) {
  if (event.target.closest('button,a,input,select,textarea')) return;
  flipJob(id);
}
function handleJobCardKey(event, id) {
  if (event.target !== event.currentTarget) return;
  if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); flipJob(id) }
}
function toggleJob(id) {
  const a = state.selected;
  if (a.includes(id)) state.selected = a.filter(x => x !== id);
  else if (a.length >= 5) { toast('Можна обрати не більше 5 професій. Прибери одну з обраних.'); return }
  else a.push(id);
  const flipped = [...document.querySelectorAll('.job-card.flipped')].map(e => e.id);
  persist(); render();
  flipped.forEach(cardId => {
    const e = document.getElementById(cardId);
    if (e) { e.classList.add('flipped'); e.setAttribute('aria-expanded', 'true') }
  });
}
