function jobsPage() { let cats = ['Усі', 'Творчість', 'Допомога людям', 'Технології', 'Бізнес', 'Наука']; let shown = jobs.filter(j => (filter === 'Усі' || j.cat === filter) && (!searchTerm || [j.title, j.cat, j.desc].join(' ').toLocaleLowerCase('uk').includes(searchTerm.toLocaleLowerCase('uk')))); return `<div class="sectionintro"><span class="tag">КРОК 01 / DISCOVER</span><h1>Які світи тебе <span class="accent">цікавлять?</span></h1><p>Тут немає неправильного вибору. Натисни на будь-яку картку: вона перевернеться й покаже, як виглядає робота зсередини. Додай до своєї колекції до п'яти професій.</p></div><div class="catalog-tools"><label class="searchbox"><span>⌕</span><input type="search" placeholder="Пошук професії чи напряму..." aria-label="Пошук професій" value="${esc(searchTerm)}" oninput="updateJobSearch(this.value)" /></label><span class="catalog-count">${shown.length} напрямів для відкриття</span></div><div class="chips">${cats.map(c => `<button class="chip ${filter === c ? 'active' : ''}" onclick="filterJobs('${c}')">${esc(c)}</button>`).join('')}</div><div class="jobs-grid">${shown.map(jobCard).join('')}</div><div class="selectionbar"><div><strong>Твоя колекція ✳ <span class="accent">${state.selected.length}/5</span></strong><div class="mini-selected">${state.selected.length ? state.selected.map(id => `<span>${esc(jobs.find(j => j.id === id)?.title || '')}</span>`).join('') : '<p>Обери професії, які хочеться дослідити</p>'}</div></div><button class="btn" onclick="beginQuiz()">Далі: тест ↗</button></div>` }
