function quizPage() { let item = q[qindex], ans = state.answers[qindex], arr = Array.isArray(ans) ? ans : [ans]; let allowed = item.kind === 'multi' ? arr.filter(Boolean).length > 0 : !!ans; return `<div class="quiz-layout"><div class="quiz-top"><span class="tag">КРОК 02 / KNOW YOURSELF</span><span class="muted" style="font-weight:800;font-size:12px">${qindex + 1} із ${q.length}</span></div><div class="progress-rail"><div style="width:${((qindex + 1) / q.length) * 100}%"></div></div><div class="quiz-card"><span class="pill">${qindex < 4 ? '✦ Твої інтереси' : qindex < 8 ? '✦ Твій спосіб мислення' : '✦ Твій професійний світ'}</span><h2>${esc(item.title)}</h2><p class="quiz-sub">${item.kind === 'multi' ? 'Можеш обрати до ' + item.max + ' варіантів.' : 'Обери один варіант, який зараз найближчий.'} Тут немає правильних відповідей.</p><div class="choices">${item.options.map(([emoji, text, key]) => `<button class="choice ${arr.includes(key) ? 'active' : ''}" onclick="answerToggle('${key}')"><span class="emoji">${emoji}</span><span>${esc(text)}</span>${arr.includes(key) ? '<span style="margin-left:auto;color:var(--purple)">✓</span>' : ''}</button>`).join('')}</div><div class="quiz-footer"><button class="btn btn-outline" onclick="quizBack()">← Назад</button><button class="btn" ${allowed ? '' : 'disabled'} onclick="quizNext()">${qindex === q.length - 1 ? 'Побачити результат ✳' : 'Продовжити →'}</button></div></div><div class="center" style="margin-top:20px"><small class="muted">Твої відповіді зберігаються тільки в цьому браузері.</small></div></div>` }
