function calculateResults() { let score = { creative: 0, people: 0, tech: 0, business: 0, science: 0, analytical: 0 }; Object.values(state.answers).forEach(a => (Array.isArray(a) ? a : [a]).forEach(x => { if (x && score[x] !== undefined) score[x] += 1 })); let rank = jobs.map(j => ({ id: j.id, score: j.tags.reduce((s, t) => s + score[t], 0) + (state.selected.includes(j.id) ? 3 : 0) })).sort((a, b) => b.score - a.score); return { score, rank } };
// ─── INSIGHTS STUDIO: explainable charts & exploratory recommendations ───
let insightTab = 'overview';
const dimensionColors = { creative: '#8061dc', people: '#27a9a1', tech: '#5987d5', business: '#e49d62', science: '#69a77c', analytical: '#d17d9c' };
function dimLabel(id) { return categories.find(([k]) => k === id)?.[1] || id }
function resultsInfo() { const r = calculateResults(), total = Object.values(r.score).reduce((a, b) => a + b, 0) || 1; const ordered = Object.entries(r.score).sort((a, b) => b[1] - a[1]); return { r, total, ordered, top: r.rank.slice(0, 5).map(row => ({ job: jobs.find(j => j.id === row.id), ...row })) } }
function radarVisual(scores) { const dims = categories.map(([k]) => k), n = dims.length, CX = 190, CY = 174, R = 112, max = Math.max(2, ...Object.values(scores)), point = (i, v) => { let a = -Math.PI / 2 + i * 2 * Math.PI / n; return [CX + R * v * Math.cos(a), CY + R * v * Math.sin(a)] }, points = vals => vals.map((v, i) => point(i, v).map(x => x.toFixed(1)).join(',')).join(' '); let circles = [.25, .5, .75, 1].map(level => `<polygon points="${points(dims.map(() => level))}" fill="none" stroke="#dddbea" stroke-width="1"/>`).join(''); let axes = dims.map((key, i) => { let [x, y] = point(i, 1), [lx, ly] = point(i, 1.27); return `<line x1="${CX}" y1="${CY}" x2="${x}" y2="${y}" stroke="#e5e3ee"/><text x="${lx}" y="${ly}" fill="#44465f" font-size="11" text-anchor="middle" dominant-baseline="middle">${esc(dimLabel(key))}</text>` }).join(''); let vertices = dims.map((k, i) => { let [x, y] = point(i, (scores[k] || 0) / max); return `<circle cx="${x}" cy="${y}" r="4.5" fill="${dimensionColors[k]}" stroke="white" stroke-width="2"><title>${esc(dimLabel(k))}: ${scores[k] || 0} виборів</title></circle>` }).join(''); return `<svg class="radar-svg" viewBox="0 0 380 350" role="img" aria-label="Пелюсткова діаграма шести сфер інтересів: ${dims.map(k => dimLabel(k) + ': ' + scores[k]).join(', ')}"><defs><linearGradient id="whymeRadar" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#7561d8" stop-opacity=".45"/><stop offset="1" stop-color="#36aaa4" stop-opacity=".22"/></linearGradient></defs>${circles}${axes}<polygon points="${points(dims.map(k => (scores[k] || 0) / max))}" fill="url(#whymeRadar)" stroke="#6b58d5" stroke-width="2.5" stroke-linejoin="round"/>${vertices}<circle cx="${CX}" cy="${CY}" r="3" fill="#6b58d5"/></svg>` }
function donutVisual(scores) { const sum = Object.values(scores).reduce((a, b) => a + b, 0) || 1; let cursor = 0; let segs = categories.map(([key]) => { const val = scores[key] || 0, offset = cursor; cursor += val; return `<circle cx="90" cy="90" r="65" fill="none" stroke="${dimensionColors[key]}" stroke-width="18" stroke-dasharray="${(val / sum * 408.407).toFixed(2)} 408.407" stroke-dashoffset="${(-offset / sum * 408.407).toFixed(2)}" transform="rotate(-90 90 90)"><title>${dimLabel(key)} — ${Math.round(val / sum * 100)}% відповідей</title></circle>` }).join(''); return `<svg viewBox="0 0 180 180" class="donut-svg" role="img" aria-label="Кругова діаграма розподілу відповідей"><circle cx="90" cy="90" r="65" fill="none" stroke="#eeedf3" stroke-width="18"/>${segs}<text x="90" y="86" text-anchor="middle" class="donut-value">${sum}</text><text x="90" y="106" text-anchor="middle" class="donut-sub">виборів</text></svg>` }
