function setDimension(id) { activeDimension = id; const d = document.querySelector('.dimension-note'); if (d) d.innerHTML = `<b>${esc(dimLabel(id))}</b><p>${dimensionDescriptions[id]}</p>`; document.querySelectorAll('.dimension-legend-item').forEach(b => b.classList.toggle('active', b.textContent.includes(dimLabel(id)))) }
function professionCompare(info) { const max = Math.max(1, ...info.r.rank.map(x => x.score)); return `<div class="insight-card full-width"><div class="viz-heading"><span class="tag">03 / МОЖЛИВІ НАПРЯМИ</span><h3>Порівняй професії</h3><p>Чим довша смуга, тим більше відповідей та обраних інтересів вона врахувала. Це не імовірність успіху.</p></div><div class="compare-grid">${info.top.map((item, i) => `<div class="compare-item"><div class="compare-rank">0${i + 1}</div><div class="compare-body"><div class="compare-top"><strong>${esc(item.job.title)}</strong><span>${item.score} балів інтересу</span></div><div class="compare-track"><i style="width:${Math.max(3, item.score / max * 100)}%;--barcolor:${dimensionColors[item.job.tags[0]] || '#8061dc'}"></i></div><p>${esc(whyJob(item.job, info.r.score))}</p><div class="compare-actions"><button class="quiet-link" onclick="openJobDetail('${item.job.id}')">Професія ↗</button><button class="quiet-link" onclick="showTrial('${item.job.id}')">Мініпроба ↗</button></div></div></div>`).join('')}</div></div>` }
